SELECT COUNT(*) FROM store.shelf_audits 
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01' 
AND status = 'empty';

SELECT DISTINCT revenue_inr / NULLIF(units_sold, 0) AS price_per_unit
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND units_sold > 0;

SELECT *
FROM store.products
WHERE name ILIKE '%toor%' OR name ILIKE '%dal%' OR name ILIKE '%arhar%';

SELECT *
FROM store.write_offs
WHERE sku = 'DAL-TOOR-1KG';

SELECT *
FROM store.goods_receipts
WHERE sku_booked = 'DAL-TOOR-1KG';

SELECT *
FROM warehouse.pallets
WHERE sscc = '029000010000010450';

SELECT *
FROM warehouse.shipping_notice_lines
WHERE sscc = '029000010000010450';

SELECT *
FROM payments.customer_complaints
WHERE sku = 'DAL-TOOR-1KG' OR product ILIKE '%toor%' OR product ILIKE '%dal%';

SELECT *
FROM warehouse.shipments
WHERE shipment_id = 'SHP-260613';

SELECT *
FROM store.write_offs
WHERE sku = 'DAL-TOOR-1KG';

SELECT *
FROM payments.customer_complaints
ORDER BY complaint_ts;

SELECT *
FROM store.products
WHERE name ILIKE '%toned%' OR name ILIKE '%milk%';

SELECT *
FROM store.write_offs
WHERE sku = 'DAL-TOOR-1KG';

SELECT sku, name, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT DISTINCT tender, till_status
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT COUNT(*) as total_attempts
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sku, name, flow, price_inr, cost_inr
FROM store.products
ORDER BY flow, name;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-06' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-11' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-16' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-21' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.daily_sales
WHERE date >= '2026-06-26' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM store.write_offs
WHERE date >= '2026-06-01' AND date <= '2026-06-30'
ORDER BY date, sku;

SELECT * FROM payments.pos_payments
WHERE bill_id IN (
    SELECT bill_id FROM store.pos_lines
    WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01'
)
ORDER BY ts;

SELECT * FROM store.stock_counts
WHERE count_ts >= '2026-06-01' AND count_ts < '2026-07-01'
ORDER BY count_ts, sku;

SELECT SUM(qty) as total_bags
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT COUNT(*) as shipment_count
FROM warehouse.shipments
WHERE dispatched_ts >= '2026-06-01' AND dispatched_ts < '2026-07-01';

SELECT * FROM store.shelf_audits
WHERE sku = 'ATTA-WW-5KG'
ORDER BY audit_ts;

SELECT SUM(refunds_inr) as total_refunds_june
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';

SELECT count(distinct bill_id) as distinct_bills
FROM store.pos_lines
WHERE bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT min(ts) as min_ts, max(ts) as max_ts, count(distinct bill_id) as bills
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT sum(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';

SELECT *
FROM store.shelf_audits
ORDER BY audit_ts;

SELECT SUM(units_sold) as total_units, SUM(revenue_inr) as total_revenue
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';

SELECT sku, name, pack, case_kg, price_inr, cost_inr
FROM store.products
ORDER BY sku;

SELECT COUNT(*) as upi_refunds_june
FROM payments.upi_refunds
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT AVG(revenue_inr) as avg_daily_revenue
FROM store.daily_sales
WHERE sku = 'SUGAR-1KG';
